obs={0:9,8:3,-2:8,-7:5,-9:6,-11:4}
valid=[]
for p in range(1,18):
    slots={}
    ok=True
    for d,c in obs.items():
        k=d%p
        if k in slots and slots[k]!=c: ok=False
        slots[k]=c
    if ok: valid.append((p,slots))
print('valid periods:',valid)
p=valid[0][0]
cycle=valid[0][1]
# For p=6 all residues observed
G=[[cycle[(c-r)%p] for c in range(17)] for r in range(17)]
print('cycle residues 0..p-1:',[cycle[i] for i in range(p)])
print('grid:')
for row in G: print(row)
